{
  "id": "ACM.2",
  "title": "ACM.2",
  "props": [
    {
      "name": "SeverityLabel",
      "ns": "http://aws.amazon.com/ns/oscal",
      "value": "HIGH"
    },
    {
      "name": "TriggerType",
      "ns": "http://aws.amazon.com/ns/oscal",
      "value": "Change Triggered"
    },
    {
      "name": "EvaluatedServices",
      "ns": "http://aws.amazon.com/ns/oscal",
      "value": "ACM"
    }
  ],
  "links": [
    {
      "href": "https://docs.aws.amazon.com/console/securityhub/ACM.2/remediation",
      "rel": "remediation"
    }
  ],
  "parts": [
    {
      "name": "overview",
      "prose": "This control checks whether RSA certificates managed by AWS Certificate Manager use a key length of at least 2,048 bits. The control fails if the key length is smaller than 2,048 bits."
    },
    {
      "name": "statement",
      "prose": "RSA certificates managed by ACM should use a key length of at least 2,048 bits"
    },
    {
      "name": "guidance",
      "prose": "For information on how to correct this issue, consult the AWS Security Hub controls documentation."
    },
    {
      "name": "assessment-method",
      "title": "acm-certificate-rsa-check",
      "props": [
        {
          "name": "TechnicalControlId",
          "ns": "http://aws.amazon.com/ns/oscal",
          "value": "acm-certificate-rsa-check",
          "class": "config-rule"
        }
      ]
    }
  ]
}
